from pathlib import Path
p = Path('/home/ubuntu/lumin-candles-store/client/src/pages/Home.tsx')
s = p.read_text()
needle = '      {termsOpen && isAuthenticated && <div className="modal-backdrop terms-backdrop">'
modal = '''      {authModalOpen && <div className="modal-backdrop auth-backdrop"><div className="auth-modal" role="dialog" aria-modal="true" aria-labelledby="auth-title"><div className="auth-modal-head"><div><span className="section-label">حساب نجدة Help</span><h2 id="auth-title">{authMode === "register" ? "أنشئ حسابك بسهولة" : "تسجيل الدخول بالبريد"}</h2><p>سيظهر اسمك فقط للطرف الآخر. البريد ورقم الجوال محفوظان للمنصة فقط.</p></div><button className="modal-close" onClick={() => setAuthModalOpen(false)} aria-label="إغلاق"><X size={18} /></button></div><div className="auth-tabs"><button className={authMode === "login" ? "active" : ""} onClick={() => setAuthMode("login")}>دخول</button><button className={authMode === "register" ? "active" : ""} onClick={() => setAuthMode("register")}>تسجيل جديد</button></div><form className="auth-form" onSubmit={submitAuth}>{authMode === "register" && <><label>الاسم الظاهر للطرف الآخر<input value={authName} onChange={(event) => setAuthName(event.target.value)} placeholder="مثال: محمد العتيبي" required /></label><label>رقم الجوال <span className="private-field-label">للمنصة فقط</span><input type="tel" value={authPhone} onChange={(event) => setAuthPhone(event.target.value)} placeholder="05xxxxxxxx" required /></label></>}<label>البريد الإلكتروني <span className="private-field-label">للمنصة فقط</span><input type="email" value={authEmail} onChange={(event) => setAuthEmail(event.target.value)} placeholder="name@example.com" required /></label><label>كلمة المرور<input type="password" minLength={8} value={authPassword} onChange={(event) => setAuthPassword(event.target.value)} placeholder="٨ أحرف على الأقل" required /></label>{authMode === "register" && <label className="auth-consent"><input type="checkbox" checked={authAccepted} onChange={(event) => setAuthAccepted(event.target.checked)} /><span>أوافق على التعامل والتواصل والدفع داخل نجدة فقط، وأتعهد بعدم التحايل أو نقل البيانات خارج المنصة.</span></label>}<button className="auth-submit" type="submit" disabled={registerMutation.isPending || loginMutation.isPending}>{registerMutation.isPending || loginMutation.isPending ? "جارٍ المعالجة..." : authMode === "register" ? "إنشاء الحساب" : "دخول آمن"}</button></form><small className="auth-privacy-note"><ShieldCheck size={13} /> الاسم الظاهر هو المعلومة العامة الوحيدة بين العميل ومقدم الخدمة.</small></div></div>}
'''
if needle not in s: raise SystemExit('terms modal not found')
p.write_text(s.replace(needle, modal + needle, 1))
